style.css:
@-moz-document domain("chess.com") {
/* Selecionador genérico do board */
  .board‑cell, .board‑cell[data-square] {
    background: #000000 !important; /* casas escuras = preto */
  }

  .board‑cell.white, .board‑cell[data-square][data-color="white"] {
    background: #ff99cc !important; /* casas claras = rosa */
  }
}
